public with sharing class RecordSearchService {

    public class SearchException extends Exception {}

    public static List<SObject> search(String objectApiName, List<String> fields,
                                       Map<String, Object> filters, String orderByField,
                                       Integer maxRows) {
        try {
            // ── Validate maxRows ──────────────────────────────────────────────
            if (maxRows == null || maxRows < 1 || maxRows > 200) {
                throw new SearchException('maxRows must be between 1 and 200.');
            }

            // ── Validate fields list ──────────────────────────────────────────
            if (fields == null || fields.isEmpty()) {
                throw new SearchException('At least one field name is required in the fields parameter.');
            }

            // ── Validate objectApiName ────────────────────────────────────────
            if (String.isBlank(objectApiName)) {
                throw new SearchException('objectApiName is required.');
            }

            Map<String, Schema.SObjectType> globalDesc = Schema.getGlobalDescribe();
            Schema.SObjectType sobjType = globalDesc.get(objectApiName.toLowerCase());
            if (sobjType == null) {
                throw new SearchException('Object not found: ' + objectApiName);
            }

            Schema.DescribeSObjectResult objDesc = sobjType.getDescribe();

            // CRUD read access on the object
            if (!objDesc.isAccessible()) {
                throw new SearchException('The running user does not have read access to object: '
                                          + objectApiName);
            }

            // Object must be queryable
            if (!objDesc.isQueryable()) {
                throw new SearchException('Object is not queryable: ' + objectApiName);
            }

            // Field map with uppercase keys for case-insensitive lookups
            Map<String, Schema.SObjectField> fieldMap = objDesc.fields.getMap();

            // ── Validate and collect requested fields ─────────────────────────
            List<String> selectFields = new List<String>();
            for (String fieldName : fields) {
                Schema.SObjectField sf = resolveField(fieldMap, fieldName);
                if (sf == null) {
                    throw new SearchException('Field "' + fieldName + '" is not a field of '
                                              + objDesc.getName() + '.');
                }
                Schema.DescribeFieldResult fr = sf.getDescribe();
                if (!fr.isAccessible()) {
                    throw new SearchException('The running user does not have field-level read access to: '
                                              + fr.getName());
                }
                // Always add Id at the start; skip duplicate Id in the list
                if (!fr.getName().equalsIgnoreCase('Id')) {
                    selectFields.add(fr.getName());
                }
            }

            // ── Build SELECT clause ───────────────────────────────────────────
            String selectClause = 'SELECT Id';
            for (String f : selectFields) {
                selectClause += ', ' + f;
            }

            // ── Build WHERE clause with safe bind variables ───────────────────
            String whereClause = '';
            Map<String, Object> bindMap = new Map<String, Object>();

            if (filters != null && !filters.isEmpty()) {
                List<String> conditions = new List<String>();
                Integer idx = 0;

                for (String filterKey : filters.keySet()) {
                    Schema.SObjectField sf = resolveField(fieldMap, filterKey);
                    if (sf == null) {
                        throw new SearchException('Filter key "' + filterKey
                                                  + '" is not a field of ' + objDesc.getName() + '.');
                    }
                    Schema.DescribeFieldResult fr = sf.getDescribe();

                    // FLS on filter field
                    if (!fr.isAccessible()) {
                        throw new SearchException('The running user does not have field-level read access to: '
                                                  + fr.getName());
                    }

                    // Must be filterable
                    if (!fr.isFilterable()) {
                        throw new SearchException('Field "' + fr.getName()
                                                  + '" is not filterable.');
                    }

                    String bindName = 'filterBind' + idx;
                    conditions.add(fr.getName() + ' = :' + bindName);
                    bindMap.put(bindName, filters.get(filterKey));
                    idx++;
                }

                if (!conditions.isEmpty()) {
                    whereClause = ' WHERE ' + String.join(conditions, ' AND ');
                }
            }

            // ── Build ORDER BY clause ─────────────────────────────────────────
            String orderClause = '';
            if (String.isNotBlank(orderByField)) {
                Schema.SObjectField sf = resolveField(fieldMap, orderByField);
                if (sf == null) {
                    throw new SearchException('Order-by field "' + orderByField
                                              + '" is not a field of ' + objDesc.getName() + '.');
                }
                Schema.DescribeFieldResult fr = sf.getDescribe();

                if (!fr.isAccessible()) {
                    throw new SearchException('The running user does not have field-level read access to: '
                                              + fr.getName());
                }
                if (!fr.isSortable()) {
                    throw new SearchException('Field "' + fr.getName() + '" is not sortable.');
                }

                orderClause = ' ORDER BY ' + fr.getName() + ' ASC';
            }

            // ── Assemble and execute query ────────────────────────────────────
            String soql = selectClause + ' FROM ' + objDesc.getName() + whereClause
                          + orderClause + ' LIMIT ' + maxRows;

            return Database.queryWithBinds(soql, bindMap, AccessLevel.USER_MODE);

        } catch (SearchException se) {
            throw se;
        } catch (Exception ex) {
            throw new SearchException('Query could not be executed: ' + ex.getMessage());
        }
    }

    // ── Private helpers ───────────────────────────────────────────────────────

    /**
     * Case-insensitive lookup of a field in the describe field-map.
     * Returns null when the field does not exist.
     */
    private static Schema.SObjectField resolveField(Map<String, Schema.SObjectField> fieldMap,
                                                    String fieldName) {
        if (fieldName == null) {
            return null;
        }
        // fieldMap keys are uppercase field API names
        return fieldMap.get(fieldName.toUpperCase());
    }
}
