// force-app/main/default/classes/OrderPayloadParser.cls
public class OrderPayloadParser {

    public class PayloadException extends Exception {}

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    public static Order parse(String body) {
        if (String.isBlank(body)) {
            throw new PayloadException('Body is null or blank');
        }

        Object parsed;
        try {
            parsed = JSON.deserializeUntyped(body);
        } catch (PayloadException pe) {
            throw pe;
        } catch (Exception e) {
            throw new PayloadException('Invalid JSON: ' + e.getMessage());
        }

        if (!(parsed instanceof Map<String, Object>)) {
            throw new PayloadException('Payload is not a JSON object');
        }

        Map<String, Object> root = (Map<String, Object>) parsed;

        Order order = new Order();
        order.lines = new List<Line>();

        // --- order number ---
        Object numVal = root.containsKey('number') ? root.get('number') : null;
        if (numVal == null || !(numVal instanceof String) || String.isBlank((String) numVal)) {
            throw new PayloadException('Missing or blank order number');
        }
        order.orderNumber = (String) numVal;

        // --- date (optional) ---
        try {
            Object dateVal = root.containsKey('date') ? root.get('date') : null;
            if (dateVal instanceof String && !String.isBlank((String) dateVal)) {
                order.orderDate = Date.valueOf((String) dateVal);
            }
        } catch (Exception e) {
            throw new PayloadException('Invalid date: ' + e.getMessage());
        }

        // --- currency (optional) ---
        Object currVal = root.containsKey('currency') ? root.get('currency') : null;
        if (currVal instanceof String) {
            order.currencyCode = (String) currVal;
        }

        // --- customer (optional nested object) ---
        Object custVal = root.containsKey('customer') ? root.get('customer') : null;
        if (custVal instanceof Map<String, Object>) {
            Map<String, Object> custMap = (Map<String, Object>) custVal;
            Object emailVal = custMap.containsKey('email') ? custMap.get('email') : null;
            if (emailVal instanceof String) {
                order.customerEmail = (String) emailVal;
            }
        } else if (custVal != null) {
            throw new PayloadException('customer must be a JSON object');
        }

        // --- lines (optional array) ---
        Object linesVal = root.containsKey('lines') ? root.get('lines') : null;
        if (linesVal != null) {
            if (!(linesVal instanceof List<Object>)) {
                throw new PayloadException('lines must be a JSON array');
            }
            List<Object> rawLines = (List<Object>) linesVal;
            for (Object item : rawLines) {
                if (!(item instanceof Map<String, Object>)) {
                    throw new PayloadException('Each line must be a JSON object');
                }
                Map<String, Object> lm = (Map<String, Object>) item;
                Line line = parseLine(lm);
                order.lines.add(line);
            }
        }

        // --- total ---
        Decimal sum = 0;
        for (Line ln : order.lines) {
            sum += ln.lineTotal;
        }
        order.total = sum;

        return order;
    }

    private static Line parseLine(Map<String, Object> lm) {
        Line line = new Line();

        // sku – required, non-blank
        Object skuVal = lm.containsKey('sku') ? lm.get('sku') : null;
        if (skuVal == null || !(skuVal instanceof String) || String.isBlank((String) skuVal)) {
            throw new PayloadException('Missing sku on line');
        }
        line.sku = (String) skuVal;

        // quantity – required, positive
        Object qtyVal = lm.containsKey('quantity') ? lm.get('quantity') : null;
        if (qtyVal == null || !(qtyVal instanceof Decimal)) {
            throw new PayloadException('Missing or invalid quantity on line for sku: ' + line.sku);
        }
        Decimal qtyDec = (Decimal) qtyVal;
        if (qtyDec <= 0) {
            throw new PayloadException('Non-positive quantity on line for sku: ' + line.sku);
        }
        line.quantity = qtyDec.intValue();

        // unitPrice – required, non-negative
        Object priceVal = lm.containsKey('unitPrice') ? lm.get('unitPrice') : null;
        if (priceVal == null || !(priceVal instanceof Decimal)) {
            throw new PayloadException('Missing or invalid unitPrice on line for sku: ' + line.sku);
        }
        line.unitPrice = (Decimal) priceVal;
        if (line.unitPrice < 0) {
            throw new PayloadException('Negative unitPrice on line for sku: ' + line.sku);
        }

        // discount – optional, null/missing → 0
        Object discVal = lm.containsKey('discount') ? lm.get('discount') : null;
        if (discVal == null || !(discVal instanceof Decimal)) {
            line.discount = 0;
        } else {
            line.discount = (Decimal) discVal;
        }

        // lineTotal = qty × unitPrice × (1 − discount), rounded HALF_UP to 2 dp
        Decimal raw = qtyDec * line.unitPrice * (Decimal.valueOf(1) - line.discount);
        line.lineTotal = raw.setScale(2, System.RoundingMode.HALF_UP);

        return line;
    }

    public static String toAcknowledgement(Order order) {
        Map<String, Object> ack = new Map<String, Object>();
        ack.put('number', order.orderNumber);
        ack.put('status', 'RECEIVED');
        ack.put('lineCount', order.lines.size());
        ack.put('total', order.total);
        return JSON.serialize(ack);
    }
}
```

**Key design decisions:**

| Concern | Approach |
|---|---|
| Invalid/extra JSON types | Caught by a blanket `try/catch` that re-throws as `PayloadException`, guaranteeing no other exception type leaks out. |
| Rounding | `Decimal.setScale(2, System.RoundingMode.HALF_UP)` — Apex's `Decimal` is arbitrary-precision (like `BigDecimal`), so `1.005` is exact and rounds to `1.01`. |
| Missing optional fields | `date`, `currency`, `customer`, `lines`, `discount` all silently become `null`/empty-list/`0`; only the fields listed in the throw-rules (`number`, `sku`, `quantity`, `unitPrice`) cause `PayloadException`. |
| Unknown properties | `deserializeUntyped` naturally ignores them — we only read the keys we care about. |
| `toAcknowledgement` | Uses `JSON.serialize` on a `Map<String,Object>` to emit exactly the four required keys as a JSON object. `lineCount` (Integer) and `total` (Decimal) serialize as JSON numbers. |

