                StageName   = 'Prospecting',
                Amount      = 1000,
                Probability = 10
            ),
            new Opportunity(
                Id          = fflib_IDGenerator.generate(Opportunity.SObjectType),
                AccountId   = accountId,
                StageName   = 'Prospecting',
                Amount      = 2000,
                Probability = 10
            ),
            new Opportunity(
