                AccountId   = accountId,
                StageName   = 'Closed Won',
                Amount      = 5000,
                Probability = 100
            )
        };

        mocks.when(selectorMock.selectOpenByAccountIds(mocks.any())).thenReturn(opps);

        Map<String, Decimal> result =
            OpportunityForecastService.weightedAmountByStage(accountIds);

        // Prospecting: 1000*10/100 + 2000*10/100 = 100 + 200 = 300
