    // (Contact, Opportunity) and OpportunityContactRole last, allowing all
    // relationships to be resolved within a single commitWork() call.
    public static final fflib_Application.UnitOfWorkFactory UnitOfWork =
        new fflib_SObjectUnitOfWork.UowFactory(
            new List<Schema.SObjectType>{
                Account.SObjectType,
                Contact.SObjectType,
                Opportunity.SObjectType,
                OpportunityContactRole.SObjectType
            }
        );

    // Selector
    public static final fflib_Application.SelectorFactory Selector =
        new fflib_SObjectSelector.SelectorFactory(
            new Map<Schema.SObjectType, fflib_SObjectSelector.ISObjectSelector>{
                Account.SObjectType => new AccountsSelector(),
                Contact.SObjectType => new ContactsSelector()
            }
        );

    // Domain – pass the Selector factory so that
    // Application.Domain.newInstance(Set<Id>) queries via the selectors above.
    public static final fflib_Application.DomainFactory Domain =
        new fflib_SObjectDomain.DomainFactory(
            Selector,
            new Map<Schema.SObjectType, fflib_SObjectDomain.IConstructable>{
                Account.SObjectType => new Accounts.Constructor()
            }
