public inherited sharing class Accounts extends fflib_SObjects implements IAccounts {

    public class Constructor extends fflib_SObjectDomain.Constructor {
        public Constructor() {
            super(Account.SObjectType);
        }

        public override fflib_ISObjects newObjects(List<SObject> records) {
            return new Accounts(records);
        }
    }

    public static IAccounts newInstance(List<Account> records) {
        return (IAccounts) Application.Domain.newObjects(records);
    }

    public static IAccounts newInstance(Set<Id> accountIds) {
        return (IAccounts) Application.Domain.newObjects(accountIds);
    }

    public Accounts(List<SObject> records) {
        super(records);
    }

    public override Schema.SObjectType getSObjectType() {
        return Account.SObjectType;
    }

    public override Schema.SObjectType getType() {
        return Account.SObjectType;
    }

    public List<Account> getAccounts() {
        List<Account> accounts = new List<Account>();
        for (SObject record : getRecords()) {
            accounts.add((Account) record);
        }
        return accounts;
    }

    public IAccounts selectByRating(String rating) {
        List<Account> filtered = new List<Account>();
        for (SObject record : getRecords()) {
            Account a = (Account) record;
            if (a.Rating == rating) {
                filtered.add(a);
            }
        }
        return newInstance(filtered);
    }

    public Set<Id> getOwnerIds() {
        Set<Id> ownerIds = new Set<Id>();
        for (SObject record : getRecords()) {
            Account a = (Account) record;
            if (a.OwnerId != null) {
                ownerIds.add(a.OwnerId);
            }
        }
        return ownerIds;
    }

    public void setRating(String rating) {
        for (SObject record : getRecords()) {
            ((Account) record).Rating = rating;
        }
    }
}
