public inherited sharing class CaseEscalationService {

    public class EscalationException extends Exception {}

    public static void escalate(Set<Id> caseIds, String reason) {

        // Blank reason – throw before touching any data
        if (String.isBlank(reason)) {
            throw new EscalationException('Reason must not be blank.');
        }

        // Nothing to process
        if (caseIds == null || caseIds.isEmpty()) {
            return;
        }

        // Load cases through the selector (mockable via Application.Selector)
        List<Case> cases = CasesSelector.newInstance().selectById(caseIds);

        // Obtain the unit of work (mockable via Application.UnitOfWork)
        fflib_ISObjectUnitOfWork uow = Application.UnitOfWork.newInstance();

        Boolean hasWork = false;

        for (Case c : cases) {
            // Skip Closed or already-escalated cases
            if (c.Status == 'Closed' || c.IsEscalated) {
                continue;
            }

            // Mutate the case
            c.IsEscalated = true;
            c.Priority    = 'High';
            uow.registerDirty(c);

            // Build the escalation task
            Task t = new Task(
                Subject      = 'Escalated: ' + reason,
                WhatId       = c.Id,
                OwnerId      = c.OwnerId,
                ActivityDate = Date.today().addDays(1),
                Priority     = 'High'
            );
            uow.registerNew(t);

            hasWork = true;
        }

        // Commit only when there is something to persist
        if (hasWork) {
            uow.commitWork();
        }
    }
}
