```apex
/**
 * Service class that creates Accounts and their related Contacts
 * using the fflib_ApexEnterprisePatterns UnitOfWork for a single,
 * bulk-safe DML transaction.
 */
public with sharing class AccountOnboardingService {

    /**
     * Creates one Account per map key and one Contact per last-name entry,
     * all persisted through a single UnitOfWork commit.
     *
     * @param contactLastNamesByAccountName  Map of Account Name -> List of Contact last names
     * @return                               List of newly created Accounts (with Ids populated)
     */
    public static List<Account> createAccountsWithContacts(
        Map<String, List<String>> contactLastNamesByAccountName) {

        // Guard clause – nothing to do
        if (contactLastNamesByAccountName == null || contactLastNamesByAccountName.isEmpty()) {
            return new List<Account>();
        }

        // One UOW instance for the entire operation; order matters (Account before Contact)
        fflib_SObjectUnitOfWork uow = new fflib_SObjectUnitOfWork(
            new List<Schema.SObjectType>{
                Account.SObjectType,
                Contact.SObjectType
            }
        );

        List<Account> newAccounts = new List<Account>();

        for (Map.Entry<String, List<String>> entry : contactLastNamesByAccountName.entrySet()) {

            Account acct = new Account(Name = entry.getKey());
            uow.registerNew(acct);
            newAccounts.add(acct);

            // Build child contacts – registerContactDependency enforces parent-first ordering
            // and automatically populates Contact.AccountId after the Account is inserted.
            if (entry.getValue() != null) {
                for (String lastName : entry.getValue()) {
                    Contact con = new Contact(LastName = lastName);
                    uow.registerContactDependency(con, acct);
                }
            }
        }

        // Single commit – bulk-safe regardless of record count
        uow.commitWork();

        return newAccounts;
    }
}
