public with sharing class OpportunityWinService {

    public static Integer markWon(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        List<Opportunity> opportunities =
            OpportunitiesSelector.newInstance().selectById(opportunityIds);

        // Only keep opportunities that are not already Closed Won
        List<Opportunity> toClose = new List<Opportunity>();
        for (Opportunity opp : opportunities) {
            if (opp.StageName != 'Closed Won') {
                opp.StageName  = 'Closed Won';
                opp.CloseDate  = Date.today();
                toClose.add(opp);
            }
        }

        if (toClose.isEmpty()) {
            return 0;
        }

        // Obtain a single unit of work from the Application factory
        fflib_SObjectUnitOfWork unitOfWork = Application.UnitOfWork.newInstance();

        // Register dirty opportunities for update
        for (Opportunity opp : toClose) {
            unitOfWork.registerDirty(
                opp,
                new Schema.SObjectField[] {
                    Opportunity.StageName,
                    Opportunity.CloseDate
                }
            );
        }

        // Register platform events – fflib will publish them via EventBus
        // in the commit job, i.e. only after all DML has succeeded.
        for (Opportunity opp : toClose) {
            Deal_Won__e evt = new Deal_Won__e();
            evt.Opportunity_Id__c = opp.Id;
            evt.Amount__c         = opp.Amount;
            unitOfWork.registerAddNew(evt);
        }

        // Single commit: DML first, events published in commit job after success.
        // If DML throws, the exception propagates and no events are published.
        unitOfWork.commit();

        return toClose.size();
    }
}
