```apex
public with sharing class FollowUpTaskService {

    /**
     * Creates a follow-up Task for each supplied Opportunity.
     * Uses Database.insert(list, false) so that a validation-rule
     * rejection on one task does NOT prevent the others from being
     * created, while staying inside the 150-DML-per-transaction limit.
     *
     * @param opportunityIds  Ids of the opportunities under review
     * @return                Set of Opportunity Ids whose task could NOT be created
     */
    public static Set<Id> createFollowUps(List<Id> opportunityIds) {

        Set<Id> failedIds = new Set<Id>();

        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return failedIds;
        }

        // --- 1 single SOQL to fetch Name + OwnerId (bulk-safe) ---
        Map<Id, Opportunity> oppMap = new Map<Id, Opportunity>();
        for (Opportunity opp : [
            SELECT Id, Name, OwnerId
            FROM Opportunity
            WHERE Id IN :opportunityIds
        ]) {
            oppMap.put(opp.Id, opp);
        }

        // --- 2 Build one Task per opportunity ---
        Date followUpDate = Date.today().addDays(7);
        List<Task> tasks = new List<Task>();
        // Parallel list so we can map each SaveResult back to its Opportunity Id
        List<Id> taskToOppId = new List<Id>();

        for (Id oppId : opportunityIds) {
            Opportunity opp = oppMap.get(oppId);
            if (opp == null) {
                // Id not found in org (deleted, no access, etc.)
                failedIds.add(oppId);
                continue;
            }

            tasks.add(new Task(
                WhatId       = opp.Id,
                OwnerId      = opp.OwnerId,
                Subject      = 'Follow up: ' + opp.Name,
                ActivityDate = followUpDate,
                Status       = 'Not Started',
                Priority     = 'Normal'
            ));
            taskToOppId.add(oppId);
        }

        if (tasks.isEmpty()) {
            return failedIds;
        }

        // --- 3 Single DML with allOrNone = false ---
        // Validation-rule failures are isolated per record; the rest commit.
        Database.SaveResult[] results = Database.insert(tasks, false);

        // --- 4 Collect failed Opportunity Ids ---
        for (Integer i = 0; i < results.size(); i++) {
            if (!results[i].isSuccess()) {
                failedIds.add(taskToOppId[i]);
            }
        }

        return failedIds;
    }
}
```

