```apex
trigger OpportunityTrigger on Opportunity (after insert, after update) {

    Set<Id> accountIds = new Set<Id>();

    if (Trigger.isInsert) {
        for (Opportunity opp : Trigger.new) {
            if (opp.AccountId != null) {
                accountIds.add(opp.AccountId);
            }
        }
    }

    if (Trigger.isUpdate) {
        for (Integer i = 0; i < Trigger.new.size(); i++) {
            Opportunity newOpp = Trigger.new[i];
            Opportunity oldOpp = Trigger.oldMap.get(newOpp.Id);

            Boolean stageChanged  = newOpp.StageName != oldOpp.StageName;
            Boolean amountChanged = newOpp.Amount    != oldOpp.Amount;
            Boolean accountChanged = newOpp.AccountId != oldOpp.AccountId;

            if (stageChanged || amountChanged) {
                if (newOpp.AccountId != null) {
                    accountIds.add(newOpp.AccountId);
                }
            }

            // If the opp moved to a different account, re-rate the old one too
            if (accountChanged) {
                if (oldOpp.AccountId != null) {
                    accountIds.add(oldOpp.AccountId);
                }
                if (newOpp.AccountId != null) {
                    accountIds.add(newOpp.AccountId);
                }
            }
        }
    }

    if (!accountIds.isEmpty()) {
        AccountRatingService.recalculate(new List<Id>(accountIds));
    }
}
