import { LightningElement, api } from 'lwc';

export default class OrderLinesPanel extends LightningElement {
    @api lines = [];
    showError = false;

    handleReset() {
        const editors = this.template.querySelectorAll('c-line-item-editor');
        editors.forEach((editor) => {
            editor.reset();
        });
    }

    handleSubmit() {
        const editors = this.template.querySelectorAll('c-line-item-editor');
        let allValid = true;

        // Validate every editor — do NOT short-circuit so that all
        // invalid lines surface their error messages simultaneously.
        editors.forEach((editor) => {
            const valid = editor.validate();
            if (!valid) {
                allValid = false;
            }
        });

        if (allValid) {
            const values = Array.from(editors).map((editor) => editor.getValue());
            this.dispatchEvent(
                new CustomEvent('submit', { detail: { lines: values } })
            );
            this.showError = false;
        } else {
            this.showError = true;
        }
    }
}
