import { LightningElement } from 'lwc';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import register from '@salesforce/apex/RegistrationController.register';

export default class EventRegistrationForm extends LightningElement {
    fullName = '';
    email = '';
    company = '';

    handleChange(event) {
        const field = event.target.dataset.field;
        const value = event.detail.value;

        if (field === 'fullName') {
            this.fullName = value;
        } else if (field === 'email') {
            this.email = value;
        } else if (field === 'company') {
            this.company = value;
        }
    }

    async handleRegister(event) {
        const fullNameInput = this.template.querySelector('[data-field="fullName"]');
        const emailInput = this.template.querySelector('[data-field="email"]');
        const companyInput = this.template.querySelector('[data-field="company"]');

        // Step 1 – work-email check (must happen before reportValidity)
        const blockedDomains = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com'];
        const emailDomain = this.email.split('@').pop().toLowerCase();

        if (blockedDomains.includes(emailDomain)) {
            emailInput.setCustomValidity('Use your work email address.');
        } else {
            emailInput.setCustomValidity('');
        }

        // Step 2 – validate every field so all messages appear at once
        const results = await Promise.all([
            fullNameInput.reportValidity(),
            emailInput.reportValidity(),
            companyInput.reportValidity()
        ]);

        // Step 3 – bail out if any field is still invalid
        if (results.some((valid) => !valid)) {
            return;
        }

        // Step 4 – call the Apex controller
        register({ fullName: this.fullName, email: this.email, company: this.company })
            .then(() => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Registered',
                        variant: 'success'
                    })
                );
            })
            .catch((error) => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Registration failed',
                        variant: 'error',
                        message: error.body.message
                    })
                );
            });
    }
}
