/**
 * EmployerService – sets the current (primary) employer affiliation for contacts
 * using NPSP's standard Primary Affiliation mechanism so that NPSP automatically
 * retires the previous employer as Former with an end date.
 */
public with sharing class EmployerService {

    /**
     * @param employerByContactId  Map of Contact Id → Organization Account Id.
     *   Null or empty input is a no-op.
     *   Max 2 SOQL, max 2 DML (within governor limits for 200 contacts).
     */
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {

        // ── guard ────────────────────────────────────────────────────────────
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        Set<Id> contactIds = new Set<Id>(employerByContactId.keySet());
        Set<Id> orgAccountIds = new Set<Id>(employerByContactId.values());

        // ── SOQL 1: contacts + their current primary affiliation's account ──
        Map<Id, Contact> existingContacts = new Map<Id, Contact>(
            [SELECT Id,
                    npe01__Primary_Affiliation__c,
                    npe01__Primary_Affiliation__r.Account__c
             FROM Contact
             WHERE Id IN :contactIds]
        );

        // ── SOQL 2: affiliations already present for these contact/org pairs ─
        List<Affiliation__c> existingAffiliations = [
            SELECT Id, Contact__c, Account__c, Type__c, Primary__c
            FROM Affiliation__c
            WHERE Contact__c IN :contactIds
              AND Account__c IN :orgAccountIds
        ];

        // Build a lookup: contactId → (accountId → Affiliation__c)
        Map<Id, Map<Id, Affiliation__c>> affByContactAndOrg = new Map<Id, Map<Id, Affiliation__c>>();
        for (Affiliation__c aff : existingAffiliations) {
            if (!affByContactAndOrg.containsKey(aff.Contact__c)) {
                affByContactAndOrg.put(aff.Contact__c, new Map<Id, Affiliation__c>());
            }
            affByContactAndOrg.get(aff.Contact__c).put(aff.Account__c, aff);
        }

        // ── determine changes ────────────────────────────────────────────────
        List<Affiliation__c> affiliationsToInsert = new List<Affiliation__c>();
        // contactId → affiliationId that the contact's primary field should point to
        Map<Id, Id> contactToNewPrimaryAffId = new Map<Id, Id>();

        for (Id conId : contactIds) {
            Id orgId = employerByContactId.get(conId);
            Contact con = existingContacts.get(conId);
            if (con == null) {
                continue; // contact no longer exists
            }

            // Already pointing at the right org via primary affiliation? → skip.
            if (con.npe01__Primary_Affiliation__r != null
                    && con.npe01__Primary_Affiliation__r.Account__c == orgId) {
                continue;
            }

            // Re-use an existing affiliation record if one is present
            Affiliation__c existing = null;
            if (affByContactAndOrg.containsKey(conId)) {
                existing = affByContactAndOrg.get(conId).get(orgId);
            }

            if (existing != null) {
                contactToNewPrimaryAffId.put(conId, existing.Id);
            } else {
                affiliationsToInsert.add(new Affiliation__c(
                    Contact__c = conId,
                    Account__c = orgId,
                    Type__c    = 'Current',
                    Primary__c = true
                ));
            }
        }

        // ── DML 1: insert any brand-new affiliations ────────────────────────
        if (!affiliationsToInsert.isEmpty()) {
            insert affiliationsToInsert;
            for (Affiliation__c aff : affiliationsToInsert) {
                contactToNewPrimaryAffId.put(aff.Contact__c, aff.Id);
            }
        }

        // ── DML 2: update contacts' primary affiliation lookup ──────────────
        // NPSP's standard mechanism (trigger / flow on this field change) will:
        //   • mark the referenced Affiliation__c as Current + Primary
        //   • retire the *previous* primary affiliation as Former with End Date = today
        //   • leave the contact in its household account untouched
        if (!contactToNewPrimaryAffId.isEmpty()) {
            List<Contact> contactsToUpdate = new List<Contact>();
            for (Id conId : contactToNewPrimaryAffId.keySet()) {
                contactsToUpdate.add(new Contact(
                    Id                              = conId,
                    npe01__Primary_Affiliation__c   = contactToNewPrimaryAffId.get(conId)
                ));
            }
            update contactsToUpdate;
        }
    }
}
```

### How it satisfies every requirement

| Requirement | Mechanism |
|---|---|
| **Current, primary affiliation + lookup** | New `Affiliation__c` is created with `Type__c='Current'`, `Primary__c=true`; the Contact's `npe01__Primary_Affiliation__c` is pointed at it. NPSP's trigger/flow on that field guarantees consistency. |
| **Previous employer → Former, non-primary, End Date = today** | Delegated entirely to NPSP's standard mechanism – updating `npe01__Primary_Affiliation__c` is the documented hook that causes the old primary affiliation to be ended. No manual update of the old `Affiliation__c` is needed (and would consume an extra DML). |
| **Contact stays in household** | The `AccountId` field on Contact is never touched. NPSP's primary-affiliation logic does not re-parent contacts. |
| **Idempotent (no duplicate / no change if already correct)** | SOQL 1 retrieves `npe01__Primary_Affiliation__r.Account__c`; if it already equals the target org the contact is skipped entirely. SOQL 2 finds an existing `Affiliation__c` for the pair so we re-use it instead of inserting a duplicate. |
| **Null / empty map** | Early-return guard. |
| **≤ 2 SOQL, ≤ 2 DML for 200 contacts** | SOQL 1 → `Contact` (1 query, up to 200 rows). SOQL 2 → `Affiliation__c` (1 query). DML 1 → `insert` new affiliations. DML 2 → `update` contacts. No other DML. |

