```java
/**
 * GiftImportService
 *
 * Stages one-off web gifts as NPSP Data Import records and processes them
 * synchronously through NPSP's Batch Data Import (BDI) engine so that
 * contact matching, household creation, and donation-processing rules
 * defined in the org's Data Import settings are applied automatically.
 *
 * Each Data Import record persists in the org as a full audit trail of
 * what was staged and what BDI did with it.
 *
 * Usage (called from an Apex REST / inbound integration handler):
 *
 *   List<GiftImportService.WebGift> gifts = ...;
 *   List<GiftImportService.ImportResult> results =
 *       GiftImportService.importGifts(gifts);
 */
public class GiftImportService {

    // ────────────────────────────────────────────────
    //  Input / Output value objects
    // ────────────────────────────────────────────────

    public class WebGift {
        public String  firstName;
        public String  lastName;
        public String  email;      // donor's personal email
        public Decimal amount;
        public Date    giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id      contactId;       // matched or newly created Contact
        public Id      opportunityId;   // newly created Opportunity (donation)
        public String  errorMessage;    // NPSP failure detail when success == false
    }

    // ────────────────────────────────────────────────
    //  Constants
    // ────────────────────────────────────────────────

    private static final String STATUS_READY    = 'Ready';
    private static final String STATUS_IMPORTED = 'Imported';

    // ────────────────────────────────────────────────
    //  Public entry point
    // ────────────────────────────────────────────────

    /**
     * Stages every gift as an npsp__DataImport__c row, processes them
     * synchronously via the BDI Apex API, and returns one ImportResult
     * per gift in the same order as the input list.
     *
     * Rows that NPSP rejects do not abort the batch; their ImportResult
     * carries the failure message from npsp__ImportFailureReasons__c.
     *
     * @param gifts  up to 200 web-gift records (null / empty → empty list)
     * @return       one ImportResult per gift, input order preserved
     */
    public static List<ImportResult> importGifts(List<WebGift> gifts) {

        List<ImportResult> results = new List<ImportResult>();

        // Guard: null or empty list → empty list
        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        // ── 1. Build Data Import records ───────────────────────────
        List<npsp__DataImport__c> dataImports = new List<npsp__DataImport__c>();

        for (WebGift g : gifts) {
            npsp__DataImport__c di = new npsp__DataImport__c(
                npsp__Contact_First_NameImport__c  = g.firstName,
                npsp__Contact_Last_NameImport__c   = g.lastName,
                npsp__Contact_EmailImport__c       = g.email,
                npsp__Donation_AmountImport__c     = g.amount,
                npsp__Donation_ReceivedDateImport__c = g.giftDate,
                npsp__Status__c                    = STATUS_READY
            );
            dataImports.add(di);
        }

        // Single DML statement for the whole batch
        insert dataImports;

        // ── 2. Process each record through BDI (synchronous) ───────
        //
        //  BDI handles contact matching / household creation /
        //  opportunity creation according to the org's Data Import
        //  settings.  A row-level failure does NOT throw; instead BDI
        //  sets the status to 'Error' and populates ImportFailureReasons__c.
        //  A system-level exception is caught so that remaining rows
        //  still get processed.

        Map<Id, String> unexpectedExceptions = new Map<Id, String>();

        for (npsp__DataImport__c di : dataImports) {
            try {
                npsp__BDI_DataImport_API.processDataImport(di.Id);
            } catch (Exception ex) {
                // Record the exception so we can surface it in the result
                // if BDI did not already update the failure-reason field.
                unexpectedExceptions.put(
                    di.Id,
                    ex.getMessage()
                );
            }
        }

        // ── 3. Re-query final state of every Data Import record ────
        //
        //  processDataImport performs internal DML, so the in-memory
        //  SObject references above do NOT reflect the updated fields.
        //  One bulk SOQL recovers everything we need.

        Map<Id, npsp__DataImport__c> processedMap = new Map<Id, npsp__DataImport__c>(
            [
                SELECT
                    Id,
                    npsp__Status__c,
                    npsp__Contact1Imported__c,
                    npsp__DonationImported__c,
                    npsp__ImportFailureReasons__c
                FROM npsp__DataImport__c
                WHERE Id IN :dataImports
            ]
        );

        // ── 4. Assemble results in input order ─────────────────────

        for (npsp__DataImport__c di : dataImports) {
            ImportResult ir          = new ImportResult();
            npsp__DataImport__c rec  = processedMap.get(di.Id);

            if (rec != null && rec.npsp__Status__c == STATUS_IMPORTED) {
                ir.success       = true;
                ir.contactId     = rec.npsp__Contact1Imported__c;
                ir.opportunityId = rec.npsp__DonationImported__c;
            } else {
                ir.success = false;

                // Prefer BDI's own failure detail (covers validation-rule
                // rejects, duplicate-match failures, etc.)
                String bdiReason = (rec != null)
                    ? rec.npsp__ImportFailureReasons__c
                    : null;

                // Fall back to the caught exception message when BDI
                // did not persist a failure reason (system error path).
                String exReason = unexpectedExceptions.get(di.Id);

                if (String.isNotBlank(bdiReason)) {
                    ir.errorMessage = bdiReason;
                } else if (String.isNotBlank(exReason)) {
                    ir.errorMessage = exReason;
                } else if (rec == null) {
                    ir.errorMessage = 'Data Import record was not found after processing.';
                } else {
                    ir.errorMessage = 'NPSP BDI returned status "' + rec.npsp__Status__c + '".';
                }
            }

            results.add(ir);
        }

        return results;
    }
}
