public class GauAllocationService {

    public class AllocationException extends Exception {}

    /**
     * Replaces all existing GAU allocations on the given Opportunity with
     * percentage-based allocations derived from percentByGauId.
     *
     * Percentage-based allocations (Amount left null, Percent populated)
     * are automatically recalculated by NPSP when the Opportunity Amount
     * changes, so no further code is needed.
     */
    public static List<npsp__Allocation__c> allocateByPercent(Id opportunityId, Map<Id, Decimal> percentByGauId) {

        // ── 1. Validate the map itself ──────────────────────────────────────
        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException(
                'percentByGauId must not be null or empty.'
            );
        }

        // ── 2. Validate each percentage value & sum ─────────────────────────
        Decimal totalPct = 0;
        for (Decimal pct : percentByGauId.values()) {
            if (pct == null) {
                throw new AllocationException(
                    'A percentage value is null. Every entry must carry a positive percentage.'
                );
            }
            if (pct <= 0) {
                throw new AllocationException(
                    'Every percentage must be greater than 0; received ' + pct + '.'
                );
            }
            totalPct += pct;
        }

        if (totalPct > 100) {
            throw new AllocationException(
                'Percentages sum to ' + totalPct + ', which exceeds 100.'
            );
        }

        // ── 3. Validate GAUs exist and are active (before ANY DML) ──────────
        Set<Id> gauIds = new Set<Id>(percentByGauId.keySet());
        List<npsp__General_Accounting_Unit__c> gaos = [
            SELECT Id, npsp__Active__c
            FROM   npsp__General_Accounting_Unit__c
            WHERE  Id IN :gauIds
        ];

        // Every Id in the map must resolve to a real record
        if (gaos.size() != gauIds.size()) {
            throw new AllocationException(
                'One or more General Accounting Unit Ids could not be found.'
            );
        }

        for (npsp__General_Accounting_Unit__c gau : gaos) {
            if (!gau.npsp__Active__c) {
                throw new AllocationException(
                    'GAU ' + gau.Id + ' is inactive and cannot be allocated to.'
                );
            }
        }

        // ── 4. Remove existing allocations on this opportunity ──────────────
        delete [
            SELECT Id
            FROM   npsp__Allocation__c
            WHERE  npsp__Opp__c = :opportunityId
        ];

        // ── 5. Build percentage-based allocations ───────────────────────────
        //
        //  Setting npsp__Percent__c and leaving npsp__Amount__c null tells NPSP
        //  this is a percentage allocation.  NPSP's triggers then compute
        //  Amount = Opportunity.Amount × Percent / 100 and keep it in sync when
        //  the Opportunity Amount is later changed (e.g. $1 000 → $2 000 causes
        //  a 60 % allocation to move from $600 to $1 200 automatically).
        //
        List<npsp__Allocation__c> allocations = new List<npsp__Allocation__c>();

        for (Id gauId : percentByGauId.keySet()) {
            allocations.add(new npsp__Allocation__c(
                npsp__Opp__c                     = opportunityId,
                npsp__General_Accounting_Unit__c  = gauId,
                npsp__Percent__c                  = percentByGauId.get(gauId)
                // npsp__Amount__c intentionally left null → percentage-based
            ));
        }

        insert allocations;

        return allocations;
    }
}
