```apex
public class FamilyService {

    /**
     * For each child→parent pair, creates a single NPSP "Parent" relationship.
     * Because NPSP uses the "List Setting" reciprocal method, the platform
     * trigger automatically creates the reciprocal (Son / Daughter / Child)
     * on the parent's side based on the child's gender.
     *
     * Constraints:
     *   – 1 SOQL query, 1 DML statement of our own (NPSP's reciprocal DML
     *     is the platform's, not ours).
     *   – Pairs whose two contacts already have ANY relationship (either
     *     direction) are skipped, making the import idempotent.
     */
    public static void linkParents(Map<Id, Id> parentIdByChildId) {

        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // --- Gather every Contact Id involved (both sides of every pair) ---
        Set<Id> allContactIds = new Set<Id>();
        allContactIds.addAll(parentIdByChildId.keySet());
        allContactIds.addAll(parentIdByChildId.values());

        // --- 1 SOQL: existing relationships touching any of those contacts ---
        List<npe5__Relationship__c> existingRels = [
            SELECT npe5__Contact__c,
                   npe5__ReciprocalRelationship__c
            FROM npe5__Relationship__c
            WHERE npe5__Contact__c              IN :allContactIds
               OR npe5__ReciprocalRelationship__c IN :allContactIds
        ];

        // Build an unordered-pair index so direction doesn't matter
        Set<String> existingPairKeys = new Set<String>();
        for (npe5__Relationship__c rel : existingRels) {
            if (rel.npe5__Contact__c != null
             && rel.npe5__ReciprocalRelationship__c != null) {
                existingPairKeys.add(pairKey(rel.npe5__Contact__c,
                                            rel.npe5__ReciprocalRelationship__c));
            }
        }

        // --- Build the list of NEW child→parent "Parent" relationships ---
        List<npe5__Relationship__c> toInsert = new List<npe5__Relationship__c>();

        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);

            // Guard against a null parent value in the map
            if (parentId == null) {
                continue;
            }

            String key = pairKey(childId, parentId);

            // Skip if a relationship between these two contacts already exists
            if (existingPairKeys.contains(key)) {
                continue;
            }

            toInsert.add(new npe5__Relationship__c(
                npe5__Contact__c               = childId,
                npe5__ReciprocalRelationship__c = parentId,
                npe5__Type__c                   = 'Parent',
                npe5__Status__c                 = 'Current'
            ));

            // Prevent a duplicate within the same call (e.g. A→B and B→A both present)
            existingPairKeys.add(key);
        }

        // --- 1 DML (of our own) ---
        if (!toInsert.isEmpty()) {
            insert toInsert;
        }
    }

    // ── private helpers ──────────────────────────────────────────────────────

    /**
     * Canonical, order-independent key for a pair of Contact Ids so that
     * (A,B) and (B,A) produce the same string.
     */
    private static String pairKey(Id a, Id b) {
        String sa = (String) a;
        String sb = (String) b;
        return sa.compareTo(sb) <= 0 ? sa + '|' + sb
                                      : sb + '|' + sa;
    }
}
