public with sharing class RecordAccessService {
    // Keeps 2,000 IDs within 10 SOQL queries, well under the allowed 20.
    private static final Integer SOQL_BATCH_SIZE = 200;

    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> editable = new Set<Id>();

        if (recordIds == null || recordIds.isEmpty()) {
            return editable;
        }

        Id currentUserId = UserInfo.getUserId();
        if (currentUserId == null) {
            return editable;
        }

        // Set iteration has no index, so convert first for safe sublist batching.
        // Also defensively ignore null IDs.
        List<Id> inputIds = new List<Id>();
        for (Id recordId : recordIds) {
            if (recordId != null) {
                inputIds.add(recordId);
            }
        }

        for (Integer start = 0; start < inputIds.size(); start += SOQL_BATCH_SIZE) {
            Integer end = start + SOQL_BATCH_SIZE;
            if (end > inputIds.size()) {
                end = inputIds.size();
            }

            List<Id> batch = inputIds.subList(start, end);

            for (UserRecordAccess access : [
                SELECT RecordId, HasEditAccess
                FROM UserRecordAccess
                WHERE UserId = :currentUserId
                  AND RecordId IN :batch
            ]) {
                if (access.HasEditAccess) {
                    editable.add(access.RecordId);
                }
            }
        }

        return editable;
    }
}
