public with sharing class TA_Contact_Queries {

    private static TA_Contact_Queries instance;

    public Map<Id, Account> accountsById { get; private set; }

    private TA_Contact_Queries() {
        accountsById = new Map<Id, Account>();
    }

    public static TA_Contact_Queries getInstance() {
        if (instance == null) {
            instance = new TA_Contact_Queries();
        }
        return instance;
    }

    /**
     * Trigger action registered as TA_Contact_Queries_Service.
     * Runs first (Order 1) in before-insert so that the parent Account
     * map is available to subsequent actions in the same execution.
     * Rebuilds the singleton on every invocation because a later DML in
     * the same transaction may involve different Accounts.
