    public class Service {

        public void execute(List<SObject> records) {
            // Reset the singleton so each trigger execution gets a fresh load
            instance = new TA_Contact_Queries();

            Set<Id> accountIds = new Set<Id>();
            for (SObject rec : records) {
                Contact c = (Contact) rec;
                if (c.AccountId != null) {
                    accountIds.add(c.AccountId);
                }
            }

            if (!accountIds.isEmpty()) {
                instance.accountsById = new Map<Id, Account>(
                    [SELECT Id,
                            BillingStreet,
                            BillingCity,
                            BillingPostalCode,
                            BillingCountry,
                            AccountSource
                     FROM Account
                     WHERE Id IN :accountIds]
                );
            }
        }
    }
}
